/* Guided offline workflows; no patient input is transmitted or persisted. */
window.ClinicalWorkspaces=function(h){
'use strict';
const {D,C,E,R,e,state,main,heading,notice,button,outputPanel,output,outputEvents,download,toast}=h;
let serial=0,patientReviewed=false;
const uid=prefix=>`${prefix}-${++serial}`;
const refs={soap:['CMS documentation principles','https://www.cms.gov/training-education/medicare-learning-networkr-mln/compliance/medicare-provider-compliance-tips/evaluation-management-services'],teach:['AHRQ teach-back','https://www.ahrq.gov/health-literacy/improve/precautions/tool5.html'],scope:['Texas written-protocol resources','https://www.pharmacy.texas.gov/drug_therapy.asp'],incident:['CMS incident-to','https://www.cms.gov/medicare/payment/fee-schedules/physician-fee-schedule/advanced-practice-non-physician-practitioners/incident-services-supplies'],pharm:['CMS pharmacist E/M clarification','https://www.cms.gov/files/document/r10505cp.pdf'],icd:['FY2027 coding guidelines','https://www.cms.gov/files/document/fy-2027-icd-10-cm-coding-guidelines.pdf'],fees:['CMS annual fee files','https://www.cms.gov/medicare/payment/fee-schedules/physician/carrier-specific-files/all-states-2026'],business:['SBA business planning','https://www.sba.gov/counseling/plan-your-business/'],mtm:['CMS Part D MTM','https://www.cms.gov/medicare/coverage/prescription-drug-coverage-contracting/medication-therapy-management'],credential:['Texas standardized credentialing','https://www.tdi.texas.gov/hmo/crform.html'],economic:['Economic-methods study (not a coefficient library)','https://pubmed.ncbi.nlm.nih.gov/11351918/'],bmi:['CDC adult BMI','https://www.cdc.gov/bmi/adult-calculator/bmi-categories.html'],cg:['NKF Cockcroft–Gault limitations','https://www.kidney.org/professionals/kdoqi/cockcroft-gault-equation-estimating-creatinine-clearance']};
refs.codes=['ASHP service-family references','https://www.ashp.org/pharmacy-practice/resource-centers/ambulatory-care/compensation-and-sustainable-business-models'];
refs.deprescribing=['CMS May2026 deprescribing guidance','https://www.cms.gov/files/document/billing-supervised-medication-deprescribing-services-under-pfs.pdf'];
refs.medicaid=['Texas Medicaid manuals','https://www.tmhp.com/resources/provider-manuals/tmppm'];
const link=id=>`<a href="${e(refs[id][1])}" target="_blank" rel="noopener noreferrer">${e(refs[id][0])} ↗</a>`;
function input(label,key,group,obj,kind='textarea',choices=[],help='',source='soap'){
 const val=String(obj[key]??''),id=`f-${group.replace(':','-')}-${key}`;
 const control=kind==='radio'?`<fieldset class="choice-set"><legend>${e(label)}</legend>${choices.map((x,i)=>`<label><input type="radio" name="${id}" data-group="${group}" data-key="${key}" value="${e(x)}"${val===x?' checked':''}>${e(x)}</label>`).join('')}</fieldset>`: `<label class="field" for="${id}">${e(label)}</label>${kind==='select'?`<select id="${id}" data-group="${group}" data-key="${key}"><option value="">Select…</option>${choices.map(x=>`<option value="${e(x)}"${x===val?' selected':''}>${e(x)}</option>`).join('')}</select>`:kind==='textarea'?`<textarea id="${id}" rows="3" data-group="${group}" data-key="${key}">${e(val)}</textarea>`:`<input id="${id}" type="${kind}" data-group="${group}" data-key="${key}" value="${e(val)}"${kind==='number'?' step="any"':''}>`}`;
 return `<div class="guided-field">${control}${help?`<details class="field-help"><summary>What to enter & why</summary><p>${e(help)}</p>${link(source)}</details>`:''}</div>`;
}
const form=(defs,group,obj)=>`<div class="guided-fields">${defs.map(d=>input(d[0],d[1],group,obj,d[2]||'textarea',d[3]||[],d[4]||'',d[5]||'soap')).join('')}</div>`;
function bind(update){main.querySelectorAll('[data-group]').forEach(el=>el.addEventListener('input',()=>{if(el.type==='radio'&&!el.checked)return;const [group,index]=el.dataset.group.split(':');const obj=group==='mtp'?state.mtps[Number(index)]:group==='event'?state.events[Number(index)]:state[group];obj[el.dataset.key]=el.value;patientReviewed=false;const check=document.getElementById('patient-review');if(check)check.checked=false;if(['encounter','mtp'].includes(group)||(group==='billing'&&['payer','service','site','modality','entity','billingRole','supervisionMode'].includes(el.dataset.key))){state.billing.record='Unknown / not reviewed';state.billing.cosign='Not completed / unknown';state.billing.cosignEvidence='';main.querySelectorAll('[data-group="billing"]').forEach(x=>{if(['record','cosign'].includes(x.dataset.key)&&x.type==='radio')x.checked=x.value===state.billing[x.dataset.key];if(x.dataset.key==='cosignEvidence')x.value='';});}update();}));}
const yes=['Unknown / not reviewed','Yes — evidence recorded','No'];
const soapDefs=[
 ['Encounter reference (de-identified)','encounterId','text',[],'Use an institution-approved de-identified reference for exports. Do not enter names, birth dates or medical record numbers here.'],
 ['Date of service','date','date',[],'Use the actual service date. Code editions and fee years depend on this date; never backdate a draft.'],
 ['Setting / modality description','setting','text',[],'Name the actual practice setting and visit modality. Office, hospital and telehealth pathways differ.'],
 ['Reason for encounter','reason','textarea',[],'State the patient goal, referral question and problems actually addressed. Example: follow-up of established hypertension treatment; difficulty using inhaler. Medical necessity should be evident.'],
 ['Author and actual role','author','text',[],'Identify the actual author and role. A student, pharmacist and billing physician have different responsibilities. This field is not authentication.'],
 ['Scope / privilege reference','authority','text',[],'Reference the executed CPA, protocol version and approved privilege covering the actions. A CPA alone does not confer payer recognition.','scope'],
 ['Subjective — what the patient reports','subjective','textarea',[],'Record symptoms, goals, actual medication use, adverse effects, access/adherence barriers and relevant history. Attribute reports to their source; distinguish missing information from negative findings.'],
 ['Objective — dated, observed facts','objective','textarea',[],'Record reconciliation, allergies, vital signs, dated laboratories, measurement units and observed device technique. Distinguish patient-reported results from verified records. Do not fabricate a normal exam.'],
 ['Assessment — reasoning and medical necessity','assessment','textarea',[],'For each addressed problem explain status versus goal, supporting facts, benefit/risk, alternatives, the medication-related cause and why the proposed action is needed. Rationale supports continuity and medical necessity; diagnosis or complexity alone does not establish an E/M level. Separate confirmed diagnoses from uncertainty.'],
 ['Plan — actions, owner, timing and contingencies','plan','textarea',[],'Record what was actually done, agreed patient actions and recommendations pending approval. Include medicine name, exact dose/units/route/timing when relevant, responsible person, escalation and return precautions only as actually agreed. Use short sentences for the patient draft.'],
 ['Patient-plan status','planStatus','radio',['Pending recommendations / mixed clinician actions','Agreed patient actions; no pending recommendations'],'Only select agreed actions after reviewing every sentence in the SOAP plan. Pending dose changes must not become patient instructions. This structured choice allows automatic reuse without retyping a patient summary.'],
 ['Monitoring — what, when, and who reviews','monitoring','textarea',[],'State measurements/tests, timing, goals and responsible reviewer. Include the agreed action if results or symptoms cross a threshold. Use patient wording when appropriate; do not invent thresholds.'],
 ['Follow-up — date/window and access','followup','textarea',[],'Record when/how to follow up, who arranges it and agreed earlier-contact instructions. This supports continuity and assessment of response.'],
 ['Education provided — patient-friendly wording','education','textarea',[],'Describe medicine/device purpose, use, risks and the skills actually taught. Use short, concrete patient wording: what to do and why. Generic “counseled” cannot establish that a specific service or skill assessment occurred.','teach'],
 ['Teach-back / show-me result','teachback','radio',['Not assessed','Needs reteaching','Demonstrated correctly after reteaching','Demonstrated correctly on first check'],'Record actual understanding or observed device steps, not just “understands.” Teach-back checks how well the team explained the plan; it is not a test of the patient.','teach'],
 ['Teach-back evidence and next teaching step','teachbackEvidence','textarea',[],'Record what the patient explained/demonstrated, gaps, reteaching and remaining needs. Evidence is useful for quality reporting. Education does not automatically create a separately billable service.','teach']
];
function eventEditor(){return `<section class="form-section"><p class="eyebrow">Shared evidence workspace</p><h2>Economic evidence linked to care</h2><p>These records appear in both this note and the business outline. No intervention receives an automatic dollar value. <a href="#evidence">Study references and provenance ↗</a></p><p class="muted">Start with a study matching the population, setting, outcome and horizon. Record the study’s uncertainty and local cost basis; a PubMed link alone does not validate a coefficient.</p><div class="actions">${button('Add evidence scenario','add-event',true)}</div>${state.events.map((x,i)=>`<article class="mtp-record"><div class="record-head"><strong>${e(x.id)}</strong><button type="button" class="text-button" data-event-remove="${i}">Remove</button></div>${form([
 ['Shared event ID','eventId','text',[],'Use one ID for one distinct economic outcome. Multiple MTPs preventing the same hospitalization share one event; repeated IDs are excluded from reports.','economic'],
 ['Related MTP IDs (comma separated)','mtpIds','text',[],'Link stable MTP identifiers, such as Problem-1. Proposed and accepted recommendations do not establish implementation. Business-only scenarios may remain unlinked.','economic'],
 ['Method','method','radio',['Risk-difference model','Direct cost comparison'],'Risk method: absolute baseline minus post-intervention risk × event cost, minus incremental intervention cost. Direct method: complete comparator cost minus intervention cost, same horizon and perspective.','economic'],
 ['Population and setting','population','textarea',[],'State the study population and local patient/service population. Explain differences that limit generalizability; never apply a universal value to every MTP.','economic'],
 ['Time horizon','horizon','text',[],'Use the same horizon for risks and costs, for example per person over 12 months. Monthly plan revenue cannot be combined with lifetime benefits.','economic'],
 ['Cost perspective','perspective','text',[],'Specify payer, health system, practice, patient or societal perspective. Savings to another party are not practice revenue. Currency is USD in this release.','economic'],
 ['USD price year','priceYear','number',[],'Identify the price year for all costs. Historical amounts require transparent adjustment and local validation before use.','economic'],
 ['Source / PMID / DOI / cost dataset','source','textarea',[],'Record the primary publication, exact table/page, cost source and extracted inputs. Keep patient narratives out of external searches.','economic'],
 ['Evidence design / uncertainty','evidenceGrade','textarea',[],'Describe trial, observational analysis, before-after comparison or modeled estimate; record confidence intervals, limitations and whether risks are absolute. A prevented event is not directly observed.','economic'],
 ['Local applicability and review','applicability','textarea',[],'Explain why the intervention, payer population and cost basis match. Name the reviewer/date or mark unreviewed; document overlaps and non-drug costs.','economic'],
 ['Baseline absolute event risk (0–1)','baseline','number',[],'Use a probability over the stated horizon, not a relative risk reduction. Blank is unknown; enter a confirmed zero explicitly.','economic'],
 ['After-intervention absolute risk (0–1)','after','number',[],'Use comparable risk over the same horizon. Do not infer risk reduction from recommendation acceptance.','economic'],
 ['Cost per event (USD)','eventCost','number',[],'Use the appropriate perspective and price year; identify what expenses are included. Avoid charges as a substitute for costs.','economic'],
 ['Incremental intervention cost (USD)','incremental','number',[],'Include added medicine, tests, labor and other incremental expenses. Enter zero only if confirmed.','economic'],
 ['Complete comparator cost (USD)','comparatorCost','number',[],'Direct comparison only: include all relevant expenses over the same horizon. Drug costs already within a total claims comparison must not be counted twice.','economic'],
 ['Complete intervention cost (USD)','implementedCost','number',[],'Direct comparison only: same perspective/horizon as comparator, including implementation expenses. Retain negative differences if costs rise.','economic']
 ],`event:${i}`,x)}</article>`).join('')}<pre class="review-output" id="economic-review"></pre></section>`;}
function eventEvents(render){document.getElementById('add-event').onclick=()=>{state.events.push({id:uid('Evidence')});render();};main.querySelectorAll('[data-event-remove]').forEach(b=>b.onclick=()=>{state.events.splice(Number(b.dataset.eventRemove),1);render();});}
function codingSection(){return `<section class="form-section"><h2>Diagnosis references from SOAP</h2><p>Local phrase matching looks at the reason and assessment. This limited bundle offers reference candidates, never a newly established diagnosis. ${link('icd')}</p><div id="diagnosis-candidates" class="review-output"></div>${form([['Confirmed candidate codes (comma separated)','confirmedCodes','text',[],'Enter only codes shown as candidates after verifying the diagnosing provider’s documentation, current index/tabular instructions, complications and specificity. Examples such as asthma and heart failure require more detail when known. No automatic use of an unspecified code.','icd'],['Diagnosis review','diagnosisReview','select',['Not reviewed','Reviewed against diagnosing-provider documentation and index/tabular instructions'],'This attestation is not a signature or coder certification. Select one supported alternative per condition family; conflicting selections produce no confirmed codes. Changing the assessment, reason or date clears the prior diagnosis review. Other diagnoses and other code editions require manual review outside this subset.','icd']],'encounter',state.encounter)}</section>`;}
function codeCatalogue(){return `<section class="form-section"><h2>Potential service-code families</h2><p>This expandable reference keeps higher E/M and other possibilities visible for payer-specific review. It is not an exhaustive CPT database, a claim recommendation or a statement that a pharmacist can personally report every code. Use current licensed descriptors and the actual payer policy/contract. ${link('codes')}</p><details class="field-help"><summary>Explore 48 CPT/HCPCS reference identifiers and their limits</summary><div class="table-wrap"><table><thead><tr><th>Family / identifiers</th><th>Required role and payment review</th></tr></thead><tbody>${R.codeFamilies.map(x=>`<tr><td><strong>${e(x.label)}</strong><br>${e(x.codes.join(', '))}</td><td>${e(x.role)}<br><small>${e(x.caveat)}</small><br><a href="${e(x.url)}" target="_blank" rel="noopener noreferrer">Original source ↗</a></td></tr>`).join('')}</tbody></table></div></details><p class="muted">CMS October2026 PFS file: 99605–99607 have status X (outside physician-fee-schedule payment). Part D sponsor MTM payment is a separate pathway; an active PFS code does not establish pharmacist provider recognition.</p><details class="field-help"><summary>Published guidance and proposed-policy watch</summary>${R.policyWatch.map(x=>`<p><strong>${e(x.status)}</strong><br>${e(x.title)}: ${e(x.note)} <a href="${e(x.url)}" target="_blank" rel="noopener noreferrer">Source ↗</a></p>`).join('')}</details></section>`;}
function contractSection(includePayer=false){return `<section class="form-section"><h2>Payer contract / alternative payment review</h2><p>Record code recognition and negotiated terms for the actual product. Original Medicare PFS rules cannot be changed by a private contract; MA, Part D, commercial and Medicaid-MCO arrangements need their own review. Texas Medicaid APM/MTM arrangements are possible strategies, not a universal legal requirement. ${link('mtm')} · ${link('medicaid')}</p>${form([
...(includePayer?[
 ['Payer product / benefit','payer','select',['Original Medicare Part B','Medicare Advantage','Texas Medicaid FFS','Texas Medicaid managed care','Commercial','Part D MTM','APM / value-based contract','Self-pay','Unknown'],'Select the actual product and benefit. These inputs are shared with the MTP service review.','codes'],
 ['Eligible billing entity / performer','entity','textarea',[],'Name the actual eligible performer, billing entity and recognition pathway. A CPA or a negotiated rate cannot replace legally required qualifications.','codes'],
 ['Billing practitioner role','billingRole','select',['MD/DO','Eligible NPP','Pharmacist — payer-recognized contract role'],'The pharmacist option is a contract-review input, not Medicare PartB provider recognition.','codes']
]:[]),
 ['Candidate contract code(s)','contractCodes','text',[],'Enter identifiers for review, such as 99214 or 99606, if the payer recognizes the performer and service. Other identifiers remain unlisted/unverified until reviewed. No E/M level or time-based units are assigned automatically.','codes'],
 ['Payer / plan / product name','planName','text',[],'Identify the specific commercial, MA, PartD or MCO product; coverage and contracts can differ within one insurer.','codes'],
 ['Contract or payer-policy reference / reviewer','contractReference','textarea',[],'Reference the executed agreement or applicable written policy, version, code recognition, reviewer and evidence location. Do not upload confidential contract documents to this site.','codes'],
 ['Benefit / authorized service / scope','contractBenefit','textarea',[],'Explain covered services, performer eligibility, attribution/referral, setting and exclusions. APM terminology does not itself authorize a claim or expand scope.','codes'],
 ['Contract effective start','contractStart','date',[],'Use the actual approved effective date covering this service.','codes'],
 ['Contract effective end / review-through date','contractEnd','date',[],'Use the documented validity period; unknown dates keep payment terms pending review.','codes'],
 ['Provider recognition and lawful eligibility reviewed','contractRecognition','radio',yes,'Verify scope, credentialing/privileges, payer-recognized performer, enrollment and billing entity. Do not assume a payer can waive provider restrictions imposed by law.','codes'],
 ['Actual service / code requirements reviewed','contractCriteria','radio',yes,'Check current descriptors, documentation, MDM/actual eligible time, units, frequency, add-ons, exclusions and overlapping services against the performed work. SOAP word count is not a level.','codes'],
 ['Evidence for actual service elements / time / exclusions','serviceElements','textarea',[],'Record what occurred, who performed each component, dated evidence and why the requested code fits. Do not reuse staff minutes for practitioner-personal codes or duplicate PartB/PartD work.','deprescribing'],
 ['Payment arrangement','contractPayment','select',['Fee-for-service with agreed codes','Negotiated per-visit fee','Per-member-per-month','Episode / bundled payment','Quality / shared-savings arrangement'],'Separate the contract payment model from the code used for service reporting. An APM may not require a CPT claim.','codes'],
 ['User-entered contracted amount (USD)','contractRate','number',[],'Enter only documented terms; missing is unknown, explicit zero is allowed. This is not a verified payment or actual collection and is never loaded automatically into business receipts.','codes'],
 ['Rate unit / settlement basis','rateUnit','text',[],'State per visit, code unit, member-month or episode; for shared savings describe the settlement basis. No multiplying by MTP count.','codes']
],'billing',state.billing)}${includePayer?input('Date of planned/actual service for contract review','date','encounter',state.encounter,'date',[],'Use the actual service date or clearly identified planning date within the contract period. This date is shared with the MTP encounter; prospective planning is not a claim.','codes'):''}<pre class="review-output" id="contract-review"></pre></section>`;}
function contractText(){const r=E.contractReview(state.encounter,state.billing,R);return ['CONTRACT / PAYER REVIEW — MANUAL CANDIDATES',r.status,'Requested codes: '+(r.requestedCodes.join(', ')||'[none]'),'Unlisted/unverified codes: '+(r.unlistedCodes.join(', ')||'[none]'),r.missing.length?'Still needed: '+r.missing.join('; '):'',r.amount!==null?'User-entered contract scenario: $'+r.amount.toFixed(2)+' USD / '+r.unit:'Contract amount remains unavailable.',...r.notes].filter(Boolean).join('\n');}
function serviceSection(){return `<section class="form-section"><h2>Internal service and payer review</h2><p>Documents support care and medical necessity. Payment also depends on the actual service, benefit, billing practitioner, scope and payer requirements. ${link('pharm')} · ${link('incident')}</p>${form([
 ['Payer product / benefit','payer','select',['Original Medicare Part B','Medicare Advantage','Texas Medicaid FFS','Texas Medicaid managed care','Commercial','Part D MTM','APM / value-based contract','Self-pay','Unknown'],'Select the actual product, not just the insurance company name. Medicare Advantage, Medicaid and commercial rules/recognition differ. An APM requires a signed arrangement; credentialing alone does not create one.','incident'],
 ['Actual service completed','service','select',['Pharmacist medication follow-up in physician office','Other service / separate review'],'Select only what occurred. The limited automated review is an office follow-up pathway; other MTM, CCM, education, hospital and preventive services need distinct rules, qualified personnel and payer review.','pharm'],
 ['Billing site','site','radio',['Nonfacility office','Hospital / facility','Other / unknown'],'A physician-office incident-to rule cannot be applied automatically to hospital outpatient or inpatient practice.','incident'],
 ['Visit modality','modality','radio',['In person','Telehealth','Other / unknown'],'This release has no patient telehealth coding rule. A supervisor’s real-time video availability is a separate question from the patient visit modality.','incident'],
 ['Eligible billing practitioner / entity / actual supervisor','entity','textarea',[],'Identify the eligible practitioner and billing entity; pharmacist author is not automatically a Medicare billing provider. Verify enrollment, privileges and the supervising practitioner.','incident'],
 ['Billing practitioner role','billingRole','select',['MD/DO','Eligible NPP','Pharmacist — payer-recognized contract role'],'The pharmacist contract option is not Medicare PartB provider recognition. CMS indicates eligible NPP-supervised incident-to services are generally paid at 85% of the physician schedule. This limited benchmark does not establish any person’s eligibility.','incident'],
 ...E.serviceGates.map(([key,label])=>[label,key,'radio',yes,'Select yes only after recording actual evidence below. Unknown is not equivalent to yes. These checks are for review; SOAP completeness cannot prove payer eligibility. Encounter fields are this tool’s local completeness controls, not a claim that every heading is a separate CMS requirement for 99211.','incident']),
 ['Direct-supervision mode','supervisionMode','radio',['Physically available','Real-time audio and video','Audio only','Unknown'],'CY2026 CMS allows qualifying real-time audio/video direct supervision for applicable services. Verify availability, state requirements and clinic policy. Audio-only is excluded; co-signing later does not substitute for supervision.','incident'],
 ['Evidence references / reviewer rationale','support','textarea',[],'Reference the actual initial plan, active involvement, medical necessity, scope/privileges, billing expense, supervision and EHR authentication. Do not invent consent, minutes or signatures.','incident'],
 ['Clinic-required MD/DO sign-off','cosign','radio',['Not completed / unknown','Completed in approved EHR by supervising MD/DO'],'This clinic’s requested sign-off control is separate from CMS rules. Check the actual EHR sign-off; this tool cannot sign or authenticate on someone’s behalf.','scope'],
 ['MD/DO sign-off evidence reference','cosignEvidence','text',[],'Reference the actual approved EHR reviewer/date/location. Do not type or create a signature here.','scope'],
 ['Texas fee locality','locality','select',Object.keys(R.localities),'Use the CMS locality key and service location county, not residence. 99 includes Bexar; other counties have distinct localities.','fees'],
 ['Actual Medicare QP status','qp','select',['nonqp','qp'],'Confirm Qualifying APM Participant status for the billing practitioner and year. A private value-based contract is not automatically Medicare QP status. Unknown yields no benchmark.','fees'],
 ['Participation / assignment','participation','select',['Participating / assignment accepted','Other / unknown'],'This release shows the published participating base schedule only. It does not calculate nonparticipating limiting charges, deductible, coinsurance, MIPS adjustments or collections.','fees']
 ],'billing',state.billing)}<p class="muted">Texas locality key: ${Object.entries(R.localities).map(([k,v])=>e(k+' '+v)).join(' · ')}.</p><pre class="review-output" id="service-review"></pre></section>`;}
function reviewText(){const r=E.serviceReview(state.encounter,state.billing),f=E.feeBenchmark(state.encounter,state.billing,r,R);return [`INTERNAL SERVICE REVIEW — NOT A CLAIM`,r.status,r.pathway,`Candidate: ${r.code||'none assigned'}${r.code?' — one service review, not one claim per MTP':''}`,r.missing.length?'Still needed:\n'+r.missing.map(x=>'• '+x).join('\n'):'',...r.warnings,`\nFEE BENCHMARK: ${f.status}`,f.base!==undefined?`Published annual 2026 nonfacility base: $${f.base.toFixed(2)}; role-adjusted reference: $${f.roleAdjusted.toFixed(2)} USD.\nLocality ${f.row.locality}; ${f.row.qp}; carrier ${f.row.carrier}; no modifier. Source R02/R03.`:'',f.reason].filter(Boolean).join('\n');}
function mtp(){
 patientReviewed=false;
 main.innerHTML=heading('ClinicalRx · Guided smart note','MTP note workspace','Document care, learn the reasoning behind each section, and export structured evidence.')+notice('Free and local to this tab. Use fictional or de-identified cases until your institution approves the workflow. Refresh clears all inputs. No EHR integration or authentication is performed.')+`<div class="actions">${button('Add medication problem','add-mtp')}${button('Load fictional case','example',true)}${button('Clear note & linked evidence','clear',true)}</div><div class="work-layout"><div><section class="form-section"><h2>Encounter & SOAP</h2><p>Open “What to enter & why” for guidance, examples and primary sources. Complete only work actually performed.</p>${form(soapDefs,'encounter',state.encounter)}</section><section class="form-section"><h2>Medication therapy problems</h2><p>Use one stable ID per problem. Acceptance, implementation and resolution are distinct. <a href="https://www.optimizingmeds.org/" target="_blank" rel="noopener noreferrer">External MTP reference ↗</a></p>${state.mtps.map((m,i)=>`<article class="mtp-record"><div class="record-head"><strong>${e(m.id)}</strong><button type="button" class="text-button" data-remove="${i}">Remove</button></div>${form([
 ['Medication / indication','medication','text',[],'Identify the relevant medicine and confirmed indication. Record dose/use in SOAP when needed; a medicine does not establish its indication.'],
 ['Problem rationale','rationale','select',D.rationales.map(r=>r.label),'Classify why the therapy may need attention. Each original label is unpriced; it is not a billing code or proof of harm.'],
 ['Supporting facts / goal / alternative','facts','textarea',[],'Link specific symptoms, dated labs, technique observations or barriers to the problem and goal. Explain why an intervention is appropriate rather than simply naming the diagnosis.'],
 ['Structured action type','actionType','radio',['Assess / reconcile','Educate / demonstrate','Recommend therapy change','Implement authorized change','Coordinate access / adherence','Monitor / follow up'],'Use a consistent action category for reporting, alongside narrative details. One category does not equal one billable service.'],
 ['Intervention discussed / performed','action','textarea',[],'State the exact action, rationale, participants and whether approval is pending. Distinguish counseling from a prescription change actually authorized and performed.'],
 ['Decision','decision','radio',['Pending','Accepted','Declined'],'Record the actual patient/prescriber decision. An accepted recommendation is not yet an implemented intervention.'],
 ['Implementation','implementation','radio',['Not implemented','Implemented'],'Select implemented only when the change occurred and you can document what, who and when.'],
 ['Actual action, responsible person and date','implementedDetails','textarea',[],'Document observed implementation or a verified record source. This supports meaningful process outcomes; do not count intent as delivery.'],
 ['Resolution','resolution','radio',['Open','Resolved'],'Resolved requires follow-up evidence of the problem outcome. A theoretical prevented adverse event is not an observed resolution.'],
 ['Follow-up evidence','followup','textarea',[],'Record dated observed outcome, patient report versus verified data, goal attainment, adverse effects and further actions. Describe limitations.']
 ],`mtp:${i}`,m)}</article>`).join('')||'<p>No problems added yet.</p>'}<p id="mtp-counts" class="status-line"></p><p id="mtp-warning" class="validation"></p></section>${codingSection()}<section class="form-section"><h2>Patient visit plan — generated from SOAP</h2><p>The draft reuses agreed SOAP actions, monitoring, follow-up and education, with plain-language headings and confirmed condition labels. A short reviewed phrase list simplifies common instructions; medication names, doses and clinical conditions are preserved. Compare the draft with SOAP. Target reading level: grades 3–5. ${link('teach')}</p><pre class="review-output" id="patient-output"></pre><p class="validation" id="patient-warning"></p><label class="check-item"><input id="patient-review" type="checkbox"><span>I checked the complete draft, all medicines/doses, pending versus agreed actions, reading level and instructions for this patient.<small>Any form edit clears this confirmation. No handout is authenticated here.</small></span></label><div class="actions">${button('Download reviewed patient draft','patient-download',true)}</div></section>${eventEditor()}${codeCatalogue()}${serviceSection()}${contractSection()}<section class="form-section"><h2>Structured reporting & approved EHR use</h2><p>Stable IDs, action categories, status and evidence fields support data reporting. Export only to an approved location. Use your EHR’s governed smart-note editor to map these fields to dropdowns/radio controls; exports are not vendor-certified imports.</p><div class="actions">${button('Download structured JSON','json-download',true)}${button('Download MTP report CSV','csv-download',true)}</div><p class="muted">JSON includes the clinical draft and review assumptions. CSV records MTP process/outcome evidence; it does not convert problems into claims or sum modeled benefits.</p></section></div>${outputPanel('SOAP draft & review appendices')}</div>`;
 const update=()=>{
  const diagnoses=E.diagnose(state.encounter,R),confirmed=E.reviewedDiagnoses(state.encounter,R),patient=E.patientDraft(state.encounter,R);
  document.getElementById('diagnosis-candidates').textContent=`${R.icdEdition} · ${diagnoses.status}\n${diagnoses.reason}\n${diagnoses.candidates.map(x=>x.code+' — '+x.description+' [candidate only]').join('\n')||'No reference candidates. Manual review required for other conditions.'}`;
  document.getElementById('service-review').textContent=reviewText();
  document.getElementById('contract-review').textContent=contractText();
  document.getElementById('economic-review').textContent=E.economicText(state.events,state.mtps);
  document.getElementById('patient-output').textContent=patient.body;
  document.getElementById('patient-warning').textContent=[`Approximate reading grade: ${patient.grade===null?'insufficient text':Math.max(0,patient.grade).toFixed(1)}. This estimate does not validate comprehension.`,patient.transformations.length?'Phrase simplifications: '+patient.transformations.join('; '):'No phrase substitutions applied.',...patient.warnings].join(' ');
  document.getElementById('patient-download').disabled=!patientReviewed||!patient.complete;
  const n=C.countStates(state.mtps);document.getElementById('mtp-counts').textContent=`Identified: ${n.identified} · Implemented with evidence: ${n.implemented} · Resolved with follow-up evidence: ${n.resolved}`;
  document.getElementById('mtp-warning').textContent=state.mtps.some(m=>(m.implementation==='Implemented'&&!String(m.implementedDetails||'').trim())||(m.resolution==='Resolved'&&!String(m.followup||'').trim()))?'Completion evidence is missing. Do not report completed outcomes for these records.':'';
  const service=reviewText()+'\n\n'+contractText();
  output((state.encounter.synthetic?'FICTIONAL LEARNING CASE — NO REAL PATIENT\n\n':'')+C.buildNote(state.encounter,state.mtps)+`\nFollow-up: ${state.encounter.followup||'[not entered]'}\nTeach-back: ${state.encounter.teachback||'[not assessed]'}\nTeach-back evidence: ${state.encounter.teachbackEvidence||'[not entered]'}\n\nDIAGNOSIS REFERENCES — CLINICIAN-REVIEWED INPUTS\n${confirmed.map(x=>x.code+' — '+x.description).join('\n')||'None confirmed within this limited reference subset.'}\nReference edition: ${R.icdEdition}; not a final coded claim.\n\n`+service+'\n\n'+E.economicText(state.events,state.mtps));
 };
 bind(update);
 main.querySelectorAll('[data-group="encounter"]').forEach(el=>el.addEventListener('input',()=>{if(['assessment','reason','date'].includes(el.dataset.key)){state.encounter.diagnosisReview='Not reviewed';state.encounter.confirmedCodes='';const box=document.getElementById('f-encounter-confirmedCodes'),sel=document.getElementById('f-encounter-diagnosisReview');if(box)box.value='';if(sel)sel.value='Not reviewed';update();}}));
 outputEvents('Pharmacist_SOAP_Draft.txt');
 document.getElementById('add-mtp').onclick=()=>{state.mtps.push({id:uid('Problem'),decision:'Pending',implementation:'Not implemented',resolution:'Open'});patientReviewed=false;mtp();};
 main.querySelectorAll('[data-remove]').forEach(b=>b.onclick=()=>{state.mtps.splice(Number(b.dataset.remove),1);patientReviewed=false;mtp();});
 document.getElementById('clear').onclick=()=>{state.encounter={};state.billing={};state.mtps=[];state.events=[];patientReviewed=false;mtp();toast('Note and linked evidence cleared.');};
 document.getElementById('example').onclick=()=>{state.encounter={synthetic:true,encounterId:'DEMO-ENCOUNTER',date:'2026-10-11',setting:'Fictional student exercise',author:'Fictional student with preceptor review pending',reason:'Follow-up of established hypertension treatment',subjective:'Fictional patient has trouble tracking home blood pressure checks.',objective:'Fictional teaching exercise. No actual laboratory or blood pressure data.',assessment:'Hypertension: need to review home readings and medicine use before changing treatment.',plan:'Keep taking your medicines as your care team told you. Write down your blood pressure checks. Bring your list to your next visit.',planStatus:'Agreed patient actions; no pending recommendations',monitoring:'Check your blood pressure as your care team told you. Write down each result and the date.',followup:'Call your clinic to set a visit in 2 weeks. Bring your medicine list and blood pressure log.',education:'Sit still before you check your blood pressure. Ask your care team to show you how to use your cuff.',teachback:'Not assessed',authority:'Learning case only; no actual CPA action'};state.mtps=[{id:uid('Problem'),medication:'Fictional medicine list',rationale:D.rationales[D.rationales.length-1].label,actionType:'Educate / demonstrate',facts:'Fictional barrier; no verified clinical outcome.',action:'Discuss a log and demonstrate the agreed measuring steps.',decision:'Pending',implementation:'Not implemented',resolution:'Open'}];state.billing={};state.events=[];patientReviewed=false;mtp();};
 document.getElementById('patient-review').onchange=event=>{patientReviewed=event.target.checked;update();};
 document.getElementById('patient-download').onclick=()=>{const p=E.patientDraft(state.encounter,R);if(!patientReviewed||!p.complete){toast('Complete and review the patient plan first.');return;}download((state.encounter.synthetic?'FICTIONAL CASE\n\n':'')+p.body+'\n\nUser marked clinician review complete; no signature generated.','Patient_Visit_Plan_Reviewed_Draft.txt');};
 document.getElementById('json-download').onclick=()=>{if(!String(state.encounter.encounterId||'').trim()){toast('Add a de-identified encounter reference before structured export.');return;}download(JSON.stringify(E.report(state.encounter,state.mtps,state.billing,state.events,R),null,2),'ClinicalRx_Structured_Draft.json');};
 document.getElementById('csv-download').onclick=()=>{if(!String(state.encounter.encounterId||'').trim()){toast('Add a de-identified encounter reference before structured export.');return;}download(E.mtpCSV(state.encounter,state.mtps,state.events),'ClinicalRx_MTP_Report.csv');};
 eventEvents(mtp);update();
}
const businessDefs=[
 ['Executive summary / value proposition','service','textarea',[],'Summarize the service, patient need, setting, operational owner, funding route and launch goal. Example: CPA-governed follow-up integrated into an existing clinic. Explain the value without promising unverified revenue.','business'],
 ['Needs assessment / target population','population','textarea',[],'Define eligibility, referral volume, unmet need and baseline data sources. Record prevalence, medication problems, access barriers and who is excluded. Differentiate published evidence from local measured demand.','business'],
 ['Service definition / scope / exclusions','services','textarea',[],'List actual visit tasks, follow-up intervals, escalation and what is outside scope. Separate medication management, device teaching and payer-defined services; each may have different requirements.','scope'],
 ['CPA / protocol / credentialing / privileges','scope','textarea',[],'Name the delegated conditions/actions, protocol owner, review schedule, license/credential verification and granted privileges. Use the Texas readiness tool. CPA authority, clinic privileges and payer recognition are separate.','scope'],
 ['Payer products / contracts / APM strategy','payer','textarea',[],'Identify product/benefit, eligible billing entity, enrollment/contract steps, service requirements and how payment is earned. Original Medicare pharmacist office E/M has a limited incident-to pathway. Keep higher E/M and other service-code families available for explicitly verified commercial policy/contracts and lawful performer recognition; there is no universal 99211 cap. Distinguish MA negotiated terms and PartD sponsor MTM from Original Medicare PFS payment. For Texas Medicaid verify the actual benefit/MCO arrangement; an APM is an option, not a universal mandate. For APMs specify attribution, performance measures, risk, settlement and contract terms.','incident'],
 ['Referral / scheduling / operating workflow','workflow','textarea',[],'Map referral, consent when required, reconciliation, assessment, intervention, clinician communication, documentation, claim review and follow-up. Assign an owner and exception pathway to each step.','business'],
 ['Staffing / capacity / responsibilities','staffing','textarea',[],'Define pharmacist, technician, scheduling and billing roles; supervision coverage, training and backup. Estimate available hours, visit length, nonvisit work and realistic capacity. Count student supervision time.','business'],
 ['Quality / clinical outcomes / equity','outcomes','textarea',[],'Define baseline, denominator, measurement period, data source and owner for each measure. Track identified/implemented/resolved MTPs separately, patient understanding, safety and access. Do not report every accepted recommendation as a benefit.','teach'],
 ['Budget / cash flow / collections evidence','budget','textarea',[],'List startup expenses, salaries/benefits, overhead, technology, supplies and incremental costs. Distinguish charges, allowed amounts, collections and subsidies. Include denials, collection delay and working capital; model realistic funding without adding noncash cost avoidance to revenue.','business'],
 ['Economic justification / evidence strategy','value','textarea',[],'Link the evidence scenarios below to care processes and payer priorities. State comparator, perspective, horizon and uncertainty. Use implementation and outcome evidence from MTP reporting. Avoid multiplying one historical dollar coefficient by every intervention.','economic'],
 ['Launch milestones / governance / renewal','milestones','textarea',[],'Set owners, dates and go/no-go criteria for scope approval, credentialing, payer contracts, staff training, pilot, audits and renewals. Submission of forms is not approval.','credential'],
 ['Risks / assumptions / audit evidence','risks','textarea',[],'Describe scope/supervision gaps, payer denials, privacy, staff capacity, inaccurate assumptions and evidence retention. Assign mitigation and review frequency. Maintain authentic approval records in approved systems.','business'],
 ['Sources / local evidence appendix','sources','textarea',[],'List exact laws/rules, policy versions, executed contract references, local baseline data and primary studies with retrieval/review dates. Educational business slides are context, not controlling law or a payer contract.','business'],
 ['Monthly completed visits (whole number)','visits','number',[],'Use realistic completed eligible visits after cancellations, capacity and referral estimates. This is a planning assumption, not billed units.','business'],
 ['Collected receipts per visit (USD)','receipts','number',[],'Use actual supported collections or clearly labeled planning assumptions. Do not substitute the fee benchmark or savings for receipts. Include denials and patient collection experience in the assumption.','business'],
 ['Variable cost per visit (USD)','variable','number',[],'Include expenses that vary with completed visits, using consistent treatment of clinician time, supplies and testing. Avoid also adding them to fixed overhead.','business'],
 ['Monthly fixed cost (USD)','fixed','number',[],'Include expenses incurred regardless of volume. Document whether salary is fixed or variable and avoid double counting. Confirm zero explicitly; blank is unknown.','business']
];
function business(){main.innerHTML=heading('ClinicalRx · Guided practice development','Practice business outline','A teaching-focused plan with section guidance, sources and linked economic evidence.')+notice('This original outline supports planning; it does not establish CPA authority, privileges, payer recognition or an APM contract. Shared economic events appear here and in the MTP note; clinical text is not copied into the business outline.')+`<div class="work-layout"><div><section class="form-section"><h2>Build the practice plan</h2><p>Open each section’s guidance for what to include, why it matters and a source. The simple monthly model uses completed visits and collected receipts, not modeled cost avoidance.</p>${form(businessDefs,'business',state.business)}</section>${codeCatalogue()}${contractSection(true)}${eventEditor()}</div>${outputPanel('Business outline & evidence')}</div>`;const update=()=>{const f=C.financialScenario(state.business);const outline=['PRACTICE BUSINESS OUTLINE — REVIEW DRAFT',...businessDefs.slice(0,13).map(([label,key,,,help,source])=>`\n${label.toUpperCase()}\n${state.business[key]||'[not entered]'}\nPlanning guide: ${help}\nReference: ${refs[source][1]}`),'\nMONTHLY COLLECTIONS SCENARIO',f.status==='SCENARIO'?`Collected receipts: $${f.revenue.toFixed(2)}\nExpenses: $${f.expense.toFixed(2)}\nOperating difference: $${f.profit.toFixed(2)}\nBreak-even completed visits: ${f.breakEven===null?'No finite break-even at this contribution':f.breakEven}\nUser-entered assumptions; no modeled benefits included in revenue. Not a full cash-flow forecast.`:`${f.status}: Enter completed visits, collections, variable and fixed costs. Blank is unknown.`, '\n'+contractText(),'\n'+E.economicText(state.events,state.mtps)];output(outline.join('\n'));document.getElementById('contract-review').textContent=contractText();document.getElementById('economic-review').textContent=E.economicText(state.events,state.mtps);};bind(update);eventEvents(business);outputEvents('Practice_Business_Outline_and_Evidence.txt');update();}
function economics(){main.innerHTML=heading('ClinicalRx · Shared evidence','Economic evidence workspace','The same evidence records are available inside the MTP and business workspaces.')+notice('No preset monetary coefficient is activated. Estimates are scenarios, not observed savings, billable services or practice receipts.')+`<div class="work-layout"><div>${eventEditor()}<section class="form-section"><h2>Historical coefficients — inactive</h2><p>Research references only. No historical amount is loaded into a scenario; local applicability and price year remain unresolved.</p><div class="table-wrap"><table><thead><tr><th>Category</th><th>Reported USD</th><th>Status</th></tr></thead><tbody>${D.historicalCoefficients.map(x=>`<tr><td>${e(x.label)}</td><td>${e(x.value)}</td><td>INACTIVE</td></tr>`).join('')}</tbody></table></div><a href="#evidence">Review sources ↗</a></section></div>${outputPanel('Evidence review')}</div>`;const update=()=>{const t=E.economicText(state.events,state.mtps);output(t);document.getElementById('economic-review').textContent=t;};bind(update);eventEvents(economics);outputEvents('Economic_Evidence_Scenarios.txt');update();}
function calculators(){main.innerHTML=heading('ClinicalRx · First clinical calculators','Adult measurement calculators','Transparent formulas, explicit assumptions and no automatic medication dosing.')+notice('Calculation is a reference aid for trained clinicians. Verify measurements and clinical context; neither result establishes a diagnosis, billing code or treatment decision.')+`<div class="work-layout"><div><section class="form-section"><h2>Adult BMI</h2><p>${link('bmi')} · Age 20+; screening measure, not a diagnosis.</p>${form([['Age in completed years','age','number',[],'This adult calculator accepts ages 20–120. Younger patients require age/sex-specific pediatric assessment.','bmi'],['Units','units','radio',['Metric','US'],'Metric: kg and cm. US: pounds and inches. Values are converted before kg/m² calculation.','bmi'],['Weight (kg or lb)','weight','number',[],'Use the unit selected above and verified measurements. Fluid accumulation and body composition can affect interpretation.','bmi'],['Height (cm or inches)','height','number',[],'Use the unit selected above. Formula: weight kg / (height m)².','bmi'],['Interpretation context','context','select',['Adult, nonpregnant; measurements checked','Pregnant / other context'],'This release does not interpret pregnancy or pediatric BMI.','bmi']],'bmi',state.bmi)}</section><section class="form-section"><h2>Cockcroft–Gault creatinine clearance</h2><p>${link('cg')} · Legacy estimate in mL/min, distinct from indexed eGFR.</p>${form([['Age in completed years','age','number',[],'Adult age 18–139; original equation has substantial population and modern assay limitations.','cg'],['Weight used in equation (kg)','weight','number',[],'Enter the clinically selected weight explicitly. Actual/ideal/adjusted weight choice can materially change the result; the calculator does not choose it.','cg'],['Weight policy / rationale','weightPolicy','text',[],'Record actual, ideal or adjusted weight and the medication-label/institutional rationale. Extreme body composition requires additional clinical judgment.','cg'],['Serum creatinine (mg/dL)','scr','number',[],'Use a verified mg/dL result during stable kidney function. Do not empirically round low values upward. No µmol/L conversion is performed here.','cg'],['Legacy equation coefficient','coefficient','radio',['Legacy male coefficient','Legacy female coefficient (×0.85)'],'Formula: (140 − age) × kg / (72 × creatinine), with historical 0.85 coefficient where selected. These binary coefficients reflect a limited legacy derivation; clinician determines applicability.','cg'],['Kidney function context','stable','select',['Stable kidney function; no AKI or dialysis','AKI / dialysis / uncertain'],'Unstable kidney function and dialysis are outside this calculator. Follow drug-specific labeling; modern guidance may favor other kidney estimates.','cg']],'cg',state.cg)}</section></div>${outputPanel('Calculated reference results')}</div>`;const update=()=>{const b=E.bmi(state.bmi),c=E.cockcroft(state.cg);output(['CLINICAL CALCULATION REFERENCE — '+E.version,'\nADULT BMI','Inputs: age '+(state.bmi.age||'[missing]')+'; weight '+(state.bmi.weight||'[missing]')+'; height '+(state.bmi.height||'[missing]')+'; '+(state.bmi.units||'[units missing]'),'Formula: kg / m²',b.status,b.value!==undefined?b.value.toFixed(1)+' '+b.units:'No result',b.reason||'Enter all required inputs.', '\nCOCKCROFT–GAULT','Inputs: age '+(state.cg.age||'[missing]')+'; weight kg '+(state.cg.weight||'[missing]')+'; creatinine mg/dL '+(state.cg.scr||'[missing]')+'; '+(state.cg.coefficient||'[coefficient missing]'),'Formula: (140 − age) × kg / (72 × creatinine mg/dL); selected legacy female coefficient multiplies by 0.85.',c.status,c.value!==undefined?c.value.toFixed(1)+' '+c.units:'No result',c.reason||'Enter all required inputs.','Weight policy: '+(state.cg.weightPolicy||'[not entered]'),'\nVerify clinical applicability. No drug dose, diagnosis or billing level is generated.','Sources: '+refs.bmi[1]+'\n'+refs.cg[1]].join('\n'));};bind(update);outputEvents('Clinical_Calculation_Reference.txt');update();}
return {mtp,business,economics,calculators};
};
